                           @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">
                        #@channel
                        @if (isMuted)
                        {
                            <span class="badge bg-warning text-dark ms-1">Muted</span>
                        }
                    </label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EditEmailNotifications;
    private bool EditPushNotifications;
    private bool EditWeeklyDigest;
    private List<string> EditMutedChannels = new();
    private bool IsSaving;
    private string? StatusMessage;

    private static readonly List<string> AllChannels = MockSettingsService.AllChannels;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EditEmailNotifications = Prefs.EmailNotifications;
            EditPushNotifications = Prefs.PushNotifications;
            EditWeeklyDigest = Prefs.WeeklyDigest;
            EditMutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted && !EditMutedChannels.Contains(channel))
            EditMutedChannels.Add(channel);
        else if (!isMuted)
            EditMutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new NotificationPrefs(
            EditEmailNotifications,
            EditPushNotifications,
            EditWeeklyDigest,
            new List<string>(EditMutedChannels));
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Notification preferences saved!";
    }
}

@using sv_e39d4da324d346f4b5bf3399d0297d7c.Models

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Security Settings</h5>
    </div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert @StatusAlertClass alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <!-- Change Password -->
        <div class="mb-4">
            <div class="d-flex align-items-center justify-content-between mb-2">
                <h6 class="text-muted mb-0">Change Password</h6>
                <button class="btn btn-sm btn-outline-secondary" @onclick="() => ShowPasswordPanel = !ShowPasswordPanel">
                    @(ShowPasswordPanel ? "Collapse" : "Expand")
                </button>
            </div>

            @if (Security?.LastPasswordChange is not null)
            {
                <small class="text-muted">Last changed: @Security.LastPasswordChange.Value.ToString("MMM dd, yyyy")</small>
            }

            @if (ShowPasswordPanel)
            {
                <div class="border rounded p-3 mt-2">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="CurrentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="NewPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="ConfirmPassword" />
                    </div>
                    <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@IsChangingPassword">
                        @if (IsChangingPassword)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Update Password
                    </button>
                </div>
            }
        </div>

        <hr />

        <!-- Two-Factor Authentication -->
        <div class="mb-4">
            <h6 class="text-muted mb-2">Two-Factor Authentication</h6>
            <div class="d-flex align-items-center gap-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@TwoFactorEnabled"
                           @onchange="e => TwoFactorEnabled = (bool)(e.Value ?? false)" />
                    <label class="form-check-label" for="twoFactor">Enable 2FA</label>
                </div>
                @if (TwoFactorEnabled)
                {
                    <span class="badge bg-success">Enabled</span>
                }
                else
                {
                    <span class="badge bg-secondary">Disabled</span>
                }
            </div>
        </div>

        <hr />

        <!-- Active Sessions -->
        <div class="mb-3">
            <h6 class="text-muted mb-3">Active Sessions</h6>

            @if (Security?.Sessions is { Count: > 0 })
            {
                <div class="table-responsive">
                    <table class="table table-hover align-middle">
                        <thead class="table-light">
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Security.Sessions)
                            {
                                var isCurrentSession = session.Id == Security.Sessions[0].Id;
                                <tr>
                                    <td>
                                        @session.Device
                                        @if (isCurrentSession)
                                        {
                                            <span class="badge bg-info ms-1">Current</span>
                                        }
                                    </td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (!isCurrentSession)
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => PromptRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">No active sessions found.</p>
            }
        </div>
    </div>
</div>

<!-- Revoke Confirmation Dialog -->
@if (SessionToRevoke is not null)
{
    <div class="modal fade show d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> from <strong>@SessionToRevoke.Location</strong>?</p>
                    <p class="text-muted small">This will sign out the device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@IsRevoking">
                        @if (IsRevoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Revoke
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }

    private bool ShowPasswordPanel;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private bool IsChangingPassword;
    private bool TwoFactorEnabled;
    private ActiveSession? SessionToRevoke;
    private bool IsRevoking;
    private string? StatusMessage;
    private string StatusAlertClass = "alert-success";

    protected override void OnParametersSet()
    {
        if (Security is not null && !_initialized)
        {
            TwoFactorEnabled = Security.TwoFactorEnabled;
            _initialized = true;
        }
    }

    private bool _initialized;

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            StatusMessage = "Please fill in all password fields.";
            StatusAlertClass = "alert-danger";
            return;
        }

        if (NewPassword != ConfirmPassword)
        {
            StatusMessage = "New password and confirmation do not match.";
            StatusAlertClass = "alert-danger";
            return;
        }

        IsChangingPassword = true;
        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        IsChangingPassword = false;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        ShowPasswordPanel = false;
        StatusMessage = "Password updated successfully!";
        StatusAlertClass = "alert-success";
    }

    private void PromptRevoke(ActiveSession session) => SessionToRevoke = session;
    private void CancelRevoke() => SessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (SessionToRevoke is null) return;
        IsRevoking = true;
        await OnRevokeSession.InvokeAsync(SessionToRevoke.Id);
        IsRevoking = false;
        SessionToRevoke = null;
        StatusMessage = "Session revoked.";
        StatusAlertClass = "alert-success";
    }

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

