@using sv_e39d4da324d346f4b5bf3399d0297d7c.Models

<div class="list-group settings-sidebar">
    @foreach (var section in Sections)
    {
        <button type="button"
                class="list-group-item list-group-item-action @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>
            @section
        </button>
    }
</div>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_e39d4da324d346f4b5bf3399d0297d7c.Models

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Profile Settings</h5>
    </div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="row mb-4">
            <div class="col-md-3 text-center">
                <div class="mb-2">
                    @if (!string.IsNullOrWhiteSpace(EditAvatarUrl))
                    {
                        <img src="@EditAvatarUrl" alt="Avatar" class="rounded-circle img-thumbnail" style="width:120px;height:120px;object-fit:cover;" />
                    }
                    else
                    {
                        <div class="rounded-circle bg-secondary d-flex align-items-center justify-content-center mx-auto" style="width:120px;height:120px;">
                            <span class="text-white fs-1">👤</span>
                        </div>
                    }
                </div>
                <small class="text-muted text-break">@EditAvatarUrl</small>
            </div>
            <div class="col-md-9">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Avatar URL</label>
                    <input type="url" class="form-control" @bind="EditAvatarUrl" />
                </div>
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label fw-semibold">Display Name</label>
            <input type="text" class="form-control" @bind="EditDisplayName" />
        </div>

        <div class="mb-3">
            <label class="form-label fw-semibold">Email</label>
            <input type="email" class="form-control" @bind="EditEmail" />
        </div>

        <div class="mb-3">
            <label class="form-label fw-semibold">Bio</label>
            <textarea class="form-control" rows="4" @bind="EditBio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                @if (IsSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">
                Discard Changes
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string EditDisplayName = "";
    private string EditEmail = "";
    private string EditAvatarUrl = "";
    private string EditBio = "";
    private bool IsSaving;
    private string? StatusMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile(Profile);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile(UserProfile profile)
    {
        EditDisplayName = profile.DisplayName;
        EditEmail = profile.Email;
        EditAvatarUrl = profile.AvatarUrl;
        EditBio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new UserProfile(EditDisplayName, EditEmail, EditAvatarUrl, EditBio);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Profile saved successfully!";
    }

    private void Discard()
    {
        if (Profile is not null)
        {
            LoadFromProfile(Profile);
        }
        StatusMessage = null;
    }
}

