@using sv_e39d4da324d346f4b5bf3399d0297d7c.Models
@using sv_e39d4da324d346f4b5bf3399d0297d7c.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Notification Preferences</h5>
    </div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="mb-4">
            <h6 class="text-muted mb-3">General</h6>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EditEmailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="EditPushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>

            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="EditWeeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h6 class="text-muted mb-3">Muted Channels</h6>
            @foreach (var channel in AllChannels)
            {
                var isMuted = EditMutedChannels.Contains(channel);
                <div class="form-check mb-2">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@isMuted"
                           @onchange="e => ToggleMute(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">
                        #@channel
                        @if (isMuted)
                        {
                            <span class="badge bg-warning text-dark ms-1">Muted</span>
                        }
                    </label>
                </div>
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
            @if (IsSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EditEmailNotifications;
    private bool EditPushNotifications;
    private bool EditWeeklyDigest;
    private List<string> EditMutedChannels = new();
    private bool IsSaving;
    private string? StatusMessage;

    private static readonly List<string> AllChannels = MockSettingsService.AllChannels;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EditEmailNotifications = Prefs.EmailNotifications;
            EditPushNotifications = Prefs.PushNotifications;
            EditWeeklyDigest = Prefs.WeeklyDigest;
            EditMutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void ToggleMute(string channel, bool isMuted)
    {
        if (isMuted && !EditMutedChannels.Contains(channel))
            EditMutedChannels.Add(channel);
        else if (!isMuted)
            EditMutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new NotificationPrefs(
            EditEmailNotifications,
            EditPushNotifications,
            EditWeeklyDigest,
            new List<string>(EditMutedChannels));
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Notification preferences saved!";
    }
}

