toolArgs.file_text:
@using sv_e39d4da324d346f4b5bf3399d0297d7c.Models

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Appearance Settings</h5>
    </div>
    <div class="card-body">
        @if (StatusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @StatusMessage
                <button type="button" class="btn-close" @onclick="() => StatusMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <h6 class="text-muted mb-2">Theme</h6>
                    @foreach (var theme in Themes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(EditTheme == theme)"
                                   @onchange="() => EditTheme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h6 class="text-muted mb-2">Font Size</h6>
                    @foreach (var size in FontSizes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(EditFontSize == size)"
                                   @onchange="() => EditFontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h6 class="text-muted mb-2">Language</h6>
                    <select class="form-select" style="max-width:250px;"
                            @bind="EditLanguage">
                        @foreach (var lang in Languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <h6 class="text-muted mb-2">Compact Mode</h6>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="EditCompactMode" />
                        <label class="form-check-label" for="compactMode">Enable compact layout</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                    @if (IsSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <h6 class="text-muted mb-2">Preview</h6>
                <div class="border rounded @PreviewBgClass @PreviewTextClass"
                     style="@PreviewStyle padding:1rem; min-height:200px; transition: all 0.3s ease;">
                    <h6 style="@PreviewFontStyle">Sample Heading</h6>
                    <p style="@PreviewFontStyle" class="@(EditCompactMode ? "mb-1" : "mb-3")">
                        This is a preview of how your content will look with the selected settings.
                    </p>
                    <div class="d-flex gap-2 @(EditCompactMode ? "flex-wrap" : "")">
                        <span class="badge @PreviewBadgeClass">Badge</span>
                        <button class="btn btn-sm @PreviewBtnClass" style="@PreviewFontStyle">Button</button>
                    </div>
                    <hr />
                    <small style="@PreviewFontStyle">
                        Theme: @EditTheme · Size: @EditFontSize · Language: @EditLanguage · Compact: @(EditCompactMode ? "On" : "Off")
                    </small>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string EditTheme = "Light";
    private string EditFontSize = "Medium";
    private string EditLanguage = "English";
    private bool EditCompactMode;
    private bool IsSaving;
    private string? StatusMessage;

    private static readonly string[] Themes = ["Light", "Dark", "System"];
    private static readonly string[] FontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            EditTheme = Settings.Theme;
            EditFontSize = Settings.FontSize;
            EditLanguage = Settings.Language;
            EditCompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private bool _initialized;

    private async Task SaveAsync()
    {
        IsSaving = true;
        var updated = new AppearanceSettings(EditTheme, EditFontSize, EditLanguage, EditCompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        StatusMessage = "Appearance settings saved!";
    }

    private string PreviewBgClass => EditTheme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string PreviewTextClass => EditTheme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string PreviewStyle => EditTheme switch
    {
        "System" => "background: linear-gradient(135deg, #f8f9fa 50%, #343a40 50%);",
        _ => ""
    };

    private string PreviewFontStyle => EditFontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private string PreviewBadgeClass => EditTheme == "Dark" ? "bg-light text-dark" : "bg-primary";
    private string PreviewBtnClass => EditTheme == "Dark" ? "btn-outline-light" : "btn-outline-primary";
}

