@page "/settings"
@using sv_e39d4da324d346f4b5bf3399d0297d7c.Models
@using sv_e39d4da324d346f4b5bf3399d0297d7c.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<h3 class="mb-4">⚙️ Settings</h3>

@if (IsLoading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-3 mb-3">
            <SettingsSidebar ActiveSection="@ActiveSection"
                            OnSectionChanged="section => ActiveSection = section" />
        </div>
        <div class="col-md-9">
            @switch (ActiveSection)
            {
                case "Profile":
                    <ProfileSection Profile="@Profile" OnSave="SaveProfileAsync" />
                    break;
                case "Notifications":
                    <NotificationsSection Prefs="@NotificationPrefs" OnSave="SaveNotificationPrefsAsync" />
                    break;
                case "Security":
                    <SecuritySection Security="@Security"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnRevokeSession="RevokeSessionAsync" />
                    break;
                case "Appearance":
                    <AppearanceSection Settings="@Appearance" OnSave="SaveAppearanceAsync" />
                    break;
            }
        </div>
    </div>
}

@code {
    private string ActiveSection = "Profile";
    private bool IsLoading = true;

    private UserProfile? Profile;
    private NotificationPrefs? NotificationPrefs;
    private SecuritySettings? Security;
    private AppearanceSettings? Appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllAsync();
        IsLoading = false;
    }

    private async Task LoadAllAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        Profile = profileTask.Result;
        NotificationPrefs = notifTask.Result;
        Security = securityTask.Result;
        Appearance = appearanceTask.Result;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        Profile = profile;
    }

    private async Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        NotificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        Appearance = settings;
    }
}

::deep .settings-sidebar .list-group-item {
    border-radius: 0;
    border-left: 3px solid transparent;
    transition: all 0.2s ease;
    cursor: pointer;
}

::deep .settings-sidebar .list-group-item:hover {
    background-color: #f0f0f0;
}

::deep .settings-sidebar .list-group-item.active {
    border-left-color: #0d6efd;
    background-color: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
}

